//! The visual registry: which unit, building and node types are drawn with
//! a model, and the manifest of each (contracts: `docs/art/peasant.md`,
//! `docs/art/static-models.md`).
//!
//! Every `*.ron` in `assets/visuals/` is a registry file (`units.ron` is
//! hand-written, `static.ron` is generated by the static art build):
//!
//! ```ron
//! (
//!     units: { "peasant": "models/peasant/peasant.model.ron" },
//!     buildings: { "house": "models/static/buildings/house/house.model.ron" },
//!     nodes: { "pine": "models/static/nodes/pine/pine.model.ron" },
//! )
//! ```
//!
//! Files are merged in file-name order: an id listed twice keeps its first
//! entry (with a warning), and a file that does not parse is skipped (with a
//! warning). An extra folder ([`ExtraVisuals`], the `--visuals` dev flag) is
//! merged the same way and then laid on top: its entries replace the base
//! folder's. Paths are asset paths, relative to the `assets/` folder.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use af_core::prelude::*;
use bevy::prelude::*;
use serde::Deserialize;

use crate::model::library::{ModelLibrary, VisualsRoot, default_assets_dir, load_unit_models};
use crate::statics::library::{StaticLibrary, load_static_models};

/// The registry folder, relative to the asset folder.
pub const VISUALS_DIR: &str = "visuals";

/// A folder of registry files, relative to the asset folder, merged on top
/// of [`VISUALS_DIR`] (its entries win). Set by the `--visuals` dev flag to
/// try models (the art pipeline's placeholders) without touching the
/// shipped registry.
#[derive(Resource, Clone, Debug, PartialEq, Eq)]
pub struct ExtraVisuals(pub PathBuf);

/// One registry file as written.
#[derive(Clone, Debug, Default, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RegistryFile {
    /// Unit id -> animated model manifest.
    #[serde(default)]
    pub units: BTreeMap<String, String>,
    /// Building id -> static model manifest.
    #[serde(default)]
    pub buildings: BTreeMap<String, String>,
    /// Resource node id -> static model manifest.
    #[serde(default)]
    pub nodes: BTreeMap<String, String>,
}

/// Parse one registry file.
pub fn parse_registry(text: &str) -> Result<RegistryFile, String> {
    ron::Options::default().from_str(text).map_err(|e| e.to_string())
}

/// A registry entry: the manifest, and the registry file that named it
/// (for messages).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Entry {
    pub manifest: String,
    pub file: String,
}

/// The merged registry: id -> entry, per section.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Registry {
    pub units: BTreeMap<String, Entry>,
    pub buildings: BTreeMap<String, Entry>,
    pub nodes: BTreeMap<String, Entry>,
}

impl Registry {
    /// Add one parsed file. An id already listed keeps its entry and the
    /// duplicate is reported.
    fn add(&mut self, file: &str, parsed: RegistryFile, warnings: &mut Vec<String>) {
        let sections = [(&mut self.units, parsed.units, "unit"), (&mut self.buildings, parsed.buildings, "building"), (&mut self.nodes, parsed.nodes, "node")];
        for (section, entries, what) in sections {
            for (id, manifest) in entries {
                match section.get(&id) {
                    Some(first) => warnings.push(format!("{file}: {what} `{id}` is already listed in {} (this entry is ignored)", first.file)),
                    None => {
                        section.insert(id, Entry { manifest, file: file.to_string() });
                    }
                }
            }
        }
    }

    /// Lay `over` on top: its entries replace these.
    fn overlay(&mut self, over: Registry) {
        self.units.extend(over.units);
        self.buildings.extend(over.buildings);
        self.nodes.extend(over.nodes);
    }

    pub fn is_empty(&self) -> bool {
        self.units.is_empty() && self.buildings.is_empty() && self.nodes.is_empty()
    }
}

/// A registry file to merge: its name for messages (`visuals/units.ron`)
/// and its text, or why it could not be read.
pub type SourceFile = (String, Result<String, String>);

/// Merge the files of one folder, in the order given.
fn merge_folder(files: Vec<SourceFile>, warnings: &mut Vec<String>) -> Registry {
    let mut registry = Registry::default();
    for (name, text) in files {
        match text.and_then(|t| parse_registry(&t)) {
            Ok(parsed) => registry.add(&name, parsed, warnings),
            Err(e) => warnings.push(format!("{name}: {e} (file skipped)")),
        }
    }
    registry
}

/// Merge the base folder's files, then the extra folder's on top (each in
/// the order given; see the module docs). Returns the registry and what
/// was skipped, one line each.
pub fn merge(base: Vec<SourceFile>, extra: Vec<SourceFile>) -> (Registry, Vec<String>) {
    let mut warnings = Vec::new();
    let mut registry = merge_folder(base, &mut warnings);
    registry.overlay(merge_folder(extra, &mut warnings));
    (registry, warnings)
}

/// The `*.ron` files of `assets/<folder>`, sorted by name; `None` when the
/// folder cannot be listed.
fn read_folder(assets: &Path, folder: &Path) -> Option<Vec<SourceFile>> {
    let dir = assets.join(folder);
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&dir).ok()?.filter_map(|e| e.ok().map(|e| e.path())).filter(|p| p.extension().is_some_and(|x| x == "ron")).collect();
    paths.sort();
    let label = |p: &Path| {
        let name = p.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default();
        format!("{}/{name}", folder.to_string_lossy().replace('\\', "/"))
    };
    Some(paths.iter().map(|p| (label(p), std::fs::read_to_string(p).map_err(|e| e.to_string()))).collect())
}

/// Read and merge `assets/visuals/*.ron`, then the `extra` folder's on top.
pub fn read_registry(assets: &Path, extra: Option<&Path>) -> (Registry, Vec<String>) {
    let mut warnings = Vec::new();
    let base = read_folder(assets, Path::new(VISUALS_DIR)).unwrap_or_else(|| {
        warnings.push(format!("{VISUALS_DIR}/: no such folder; everything is drawn as boxes"));
        Vec::new()
    });
    let extra = match extra {
        Some(folder) => {
            let files = read_folder(assets, folder).unwrap_or_default();
            if files.is_empty() {
                warnings.push(format!("{}/: no registry files (`*.ron`) there", folder.to_string_lossy()));
            }
            files
        }
        None => Vec::new(),
    };
    let (registry, more) = merge(base, extra);
    warnings.extend(more);
    (registry, warnings)
}

/// Startup: read the registry and the manifests it names, and start
/// loading the models of each library not already there (`--no-models`, or
/// a test, inserts its own).
pub(crate) fn load_visuals(
    mut commands: Commands,
    data: Res<Data>,
    server: Res<AssetServer>,
    root: Option<Res<VisualsRoot>>,
    extra: Option<Res<ExtraVisuals>>,
    units: Option<Res<ModelLibrary>>,
    statics: Option<Res<StaticLibrary>>,
) {
    if units.is_some() && statics.is_some() {
        return;
    }
    let (registry, dir) = match root.map(|r| r.0.clone()).or_else(default_assets_dir) {
        Some(dir) => {
            let (registry, warnings) = read_registry(&dir, extra.as_deref().map(|e| e.0.as_path()));
            for w in &warnings {
                warn!("{w}");
            }
            (registry, dir)
        }
        None => {
            warn!("no assets folder found: everything is drawn as boxes");
            (Registry::default(), PathBuf::new())
        }
    };
    if units.is_none() {
        commands.insert_resource(load_unit_models(&data, &registry.units, &dir, &server));
    }
    if statics.is_none() {
        commands.insert_resource(load_static_models(&data, &registry, &dir, &server));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn file(name: &str, text: &str) -> SourceFile {
        (name.to_string(), Ok(text.to_string()))
    }

    fn manifest(section: &BTreeMap<String, Entry>, id: &str) -> Option<String> {
        section.get(id).map(|e| e.manifest.clone())
    }

    #[test]
    fn the_shipped_registry_parses_and_names_the_peasant() {
        let shipped = include_str!("../../../assets/visuals/units.ron");
        let r = parse_registry(shipped).unwrap_or_else(|e| panic!("assets/visuals/units.ron: {e}"));
        assert_eq!(r.units.get("peasant").map(String::as_str), Some("models/peasant/peasant.model.ron"));
    }

    #[test]
    fn sections_are_optional_but_unknown_ones_are_errors() {
        let r = parse_registry(r#"(nodes: {"pine": "p.model.ron"}) // a comment"#).unwrap();
        assert!(r.units.is_empty() && r.buildings.is_empty());
        assert_eq!(r.nodes.get("pine").map(String::as_str), Some("p.model.ron"));
        assert_eq!(parse_registry("()").unwrap(), RegistryFile::default());
        assert!(parse_registry(r#"(node: {"pine": "p.model.ron"})"#).is_err(), "a misspelt section is not silently ignored");
        assert!(parse_registry(r#"{"peasant": "models/peasant/peasant.model.ron"}"#).is_err(), "the old bare map");
        assert!(parse_registry(r#"(units: {"peasant": 3})"#).is_err());
    }

    #[test]
    fn files_merge_first_entry_wins_and_broken_files_are_skipped() {
        let (r, warnings) = merge(
            vec![
                file("visuals/a.ron", r#"(units: {"peasant": "a/peasant.ron"}, nodes: {"pine": "a/pine.ron"})"#),
                file("visuals/b.ron", r#"(nodes: {"pine": "b/pine.ron", "oak": "b/oak.ron"}, buildings: {"house": "b/house.ron"})"#),
                file("visuals/broken.ron", "(units: {"),
                ("visuals/locked.ron".to_string(), Err("permission denied".to_string())),
            ],
            Vec::new(),
        );
        assert_eq!(manifest(&r.units, "peasant").as_deref(), Some("a/peasant.ron"));
        assert_eq!(manifest(&r.nodes, "pine").as_deref(), Some("a/pine.ron"), "first wins");
        assert_eq!(r.nodes["pine"].file, "visuals/a.ron");
        assert_eq!(manifest(&r.nodes, "oak").as_deref(), Some("b/oak.ron"));
        assert_eq!(manifest(&r.buildings, "house").as_deref(), Some("b/house.ron"));
        let w = warnings.join("\n");
        for needle in ["visuals/b.ron: node `pine` is already listed in visuals/a.ron", "visuals/broken.ron:", "visuals/locked.ron: permission denied"] {
            assert!(w.contains(needle), "{needle} in:\n{w}");
        }
        assert_eq!(warnings.len(), 3, "{w}");
    }

    #[test]
    fn the_extra_folder_is_laid_on_top() {
        let (r, warnings) = merge(
            vec![file("visuals/static.ron", r#"(nodes: {"pine": "real/pine.ron", "oak": "real/oak.ron"})"#), file("visuals/units.ron", r#"(units: {"peasant": "p.ron"})"#)],
            vec![
                file("visuals-placeholders/static.ron", r#"(nodes: {"pine": "stand-in/pine.ron"}, buildings: {"house": "stand-in/house.ron"})"#),
                file("visuals-placeholders/x.ron", r#"(nodes: {"pine": "second/pine.ron"})"#),
            ],
        );
        assert_eq!(manifest(&r.nodes, "pine").as_deref(), Some("stand-in/pine.ron"), "the extra folder wins");
        assert_eq!(r.nodes["pine"].file, "visuals-placeholders/static.ron");
        assert_eq!(manifest(&r.nodes, "oak").as_deref(), Some("real/oak.ron"), "untouched entries stay");
        assert_eq!(manifest(&r.units, "peasant").as_deref(), Some("p.ron"));
        assert_eq!(manifest(&r.buildings, "house").as_deref(), Some("stand-in/house.ron"));
        // Inside one folder the first entry still wins.
        assert_eq!(warnings.len(), 1);
        assert!(warnings[0].contains("visuals-placeholders/x.ron: node `pine` is already listed in visuals-placeholders/static.ron"), "{warnings:?}");
    }

    #[test]
    fn folders_are_read_in_file_name_order() {
        let dir = std::env::temp_dir().join(format!("af_render_registry_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("visuals")).unwrap();
        std::fs::create_dir_all(dir.join("extra")).unwrap();
        std::fs::write(dir.join("visuals/b.ron"), r#"(nodes: {"pine": "b.ron"})"#).unwrap();
        std::fs::write(dir.join("visuals/a.ron"), r#"(nodes: {"pine": "a.ron"})"#).unwrap();
        std::fs::write(dir.join("visuals/notes.txt"), "not a registry").unwrap();
        std::fs::write(dir.join("extra/static.ron"), r#"(buildings: {"house": "h.ron"})"#).unwrap();
        let (r, warnings) = read_registry(&dir, Some(Path::new("extra")));
        assert_eq!(manifest(&r.nodes, "pine").as_deref(), Some("a.ron"));
        assert_eq!(r.nodes["pine"].file, "visuals/a.ron");
        assert_eq!(manifest(&r.buildings, "house").as_deref(), Some("h.ron"));
        assert_eq!(warnings.len(), 1, "only the duplicate pine: {warnings:?}");
        let (_, warnings) = read_registry(&dir, Some(Path::new("missing")));
        assert!(warnings.iter().any(|w| w.contains("missing/")), "{warnings:?}");
        let (r, warnings) = read_registry(&dir.join("nowhere"), None);
        assert!(r.is_empty() && warnings[0].contains("no such folder"));
        let _ = std::fs::remove_dir_all(&dir);
    }
}
